AND (
    1 = 0

        OR (${a}.ORG_MSTR_CODE IS NULL OR ${a}.ORG_CODE IS NULL)


        OR (${a}.ORG_MSTR_CODE = #{district.regionCode} AND ${a}.ORG_CODE = #{district.districtCode})

)

    AND ${a}.ORG_MSTR_CODE = #{regionCode}
    AND ${a}.ORG_CODE = #{districtCode}

mapper.select:
SELECT CAST(s.GOAL_ID AS CHAR) AS id, s.ORG_MSTR_CODE AS regionCode, s.ORG_CODE AS districtCode,
       r.ORG_MSTR_NAME_HAN AS regionName, d.ORG_NAME_HAN AS districtName,
       s.BAN_CODE AS className, s.FROM_DATE AS `from`, s.TO_DATE AS `to`,
       s.STAGE_CODE AS stageId, c.ITEM_NAME AS stageName, s.PERIOD_CODE AS periodUnit, s.TARGET_CNT AS target,
       DATE_FORMAT(s.SYS_MUSR_DTTM, '%Y-%m-%dT%H:%i:%s') AS version
  FROM GOALMSTR s

  LEFT JOIN CODEDTL c ON c.LIB_ID = s.LIB_ID AND c.GROUP_CODE = 'STAGE' AND c.ITEM_CODE = s.STAGE_CODE
 WHERE s.LIB_ID = #{libraryId}

 AND s.GOAL_ID = #{id}
 AND s.TO_DATE >= #{from}
 AND s.FROM_DATE <= #{to}
 AND s.BAN_CODE = #{className}


        AND s.STAGE_CODE IS NULL
        AND s.STAGE_CODE = #{stage}


 ORDER BY s.FROM_DATE DESC, r.SORT_NO, d.SORT_NO, s.BAN_CODE, s.GOAL_ID

SELECT CAST(s.ORG_ACT_ID AS CHAR) AS id, s.EMPL_ID AS memberId, s.EMPL_CODE AS memberCode, s.EMPL_NAME AS memberName, s.ACT_MONTH AS `month`, s.ACT_DATE AS `date`, s.PERIOD_KEY AS period, s.ACT_STATUS_CODE AS status, s.ORG_MSTR_CODE AS regionCode, s.ORG_CODE AS districtCode, r.ORG_MSTR_NAME_HAN AS regionName, d.ORG_NAME_HAN AS districtName, DATE_FORMAT(s.SYS_MUSR_DTTM, '%Y-%m-%dT%H:%i:%s') AS version FROM ORGACT s
WHERE s.LIB_ID = #{libraryId}
AND s.ORG_ACT_ID = #{id} AND s.ACT_MONTH = #{month} AND s.ACT_DATE = #{date}
AND (s.ACT_DATE >= #{from} OR (s.ACT_DATE IS NULL AND s.ACT_MONTH >= #{fromMonth}))
AND (s.ACT_DATE <= #{to} OR (s.ACT_DATE IS NULL AND s.ACT_MONTH <= #{toMonth}))
ORDER BY s.PERIOD_KEY DESC, r.SORT_NO, d.SORT_NO, s.EMPL_NAME, s.ORG_ACT_ID

SELECT CAST(s.SOC_DTL_ID AS CHAR) AS id, s.SOC_ID AS programId, m.SOC_NAME AS programName,
       s.INFLOW_DATE AS `date`, s.INFLOW_NAME AS name, s.INTRO_NAME AS introducerName,
       s.ORG_MSTR_CODE AS regionCode, s.ORG_CODE AS districtCode,
       r.ORG_MSTR_NAME_HAN AS regionName, d.ORG_NAME_HAN AS districtName,
       s.STATUS_CODE AS status, s.CONVERTED_DTTM AS convertedAt
  FROM SOCDTL s

  LEFT JOIN SOCMSTR m ON m.LIB_ID = s.LIB_ID AND m.SOC_ID = s.SOC_ID
 WHERE s.LIB_ID = #{libraryId}

 AND s.SOC_ID = #{programId}
 AND s.INFLOW_DATE >= #{from}
 AND s.INFLOW_DATE <= #{to}
AND s.STATUS_CODE = #{socialStatus}

    AND (LOCATE(#{search}, LOWER(s.INFLOW_NAME)) > 0 OR LOCATE(#{search}, LOWER(s.INTRO_NAME)) > 0)

 ORDER BY s.INFLOW_DATE DESC, s.SOC_DTL_ID DESC

SELECT s.SOC_ID AS programId, m.SOC_NAME AS programName, DATE_FORMAT(s.INFLOW_DATE, '%Y-%m') AS `month`,
       COUNT(*) AS total, SUM(s.STATUS_CODE = 'pending') AS pending, SUM(s.STATUS_CODE = 'converted') AS converted
  FROM SOCDTL s
  LEFT JOIN SOCMSTR m ON m.LIB_ID = s.LIB_ID AND m.SOC_ID = s.SOC_ID
 WHERE s.LIB_ID = #{libraryId}

 AND s.SOC_ID = #{programId}
 AND s.INFLOW_DATE >= #{from}
 AND s.INFLOW_DATE <= #{to}
 GROUP BY s.SOC_ID, m.SOC_NAME, DATE_FORMAT(s.INFLOW_DATE, '%Y-%m')
 ORDER BY `month` DESC, m.SOC_NAME, s.SOC_ID

SELECT COUNT(*) FROM GOALMSTR
 WHERE LIB_ID = #{libraryId}
   AND ((#{newDistrict} IS NULL AND ORG_CODE IS NULL) OR (ORG_MSTR_CODE = #{newRegion} AND ORG_CODE = #{newDistrict}))
   AND BAN_CODE <=> #{className} AND STAGE_CODE <=> #{stageId}
   AND FROM_DATE = #{from} AND TO_DATE = #{to}
 AND GOAL_ID != #{id}
